        if grid[r][0] == source: sides.append(0)
        if grid[r][w-1] == source: sides.append(w-1)
        for edge in sides:
            targets = [c for c in range(w) if grid[r][c] == ray]
            if targets:
                # Paint from the target to the active boundary source.
                t = min(targets, key=lambda c: abs(c-edge))
                lo, hi = sorted((t, edge))
                for c in range(lo, hi+1):
                    if c != edge: out[r][c] = ray
                out[r][t] = 4
            else:
                step = 1 if edge == 0 else -1
                c = edge + step
                while 0 <= c < w:
                    out[r][c] = ray
                    c += step
    return out

